-- Run in Supabase SQL editor. RLS policies are intentionally deny-by-default.
create extension if not exists "pgcrypto";
create type public.order_status as enum ('pending','paid','processing','completed','failed','refunded','cancelled');
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text, role text not null default 'customer' check (role in ('customer','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), profile_id uuid unique not null references public.profiles(id) on delete cascade, company_name text, phone text, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category text not null, name text not null, slug text unique not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.pricing (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, currency text not null default 'AUD', amount_cents integer not null check(amount_cents>=0), renewal_amount_cents integer check(renewal_amount_cents>=0), billing_period text, active boolean not null default true, created_at timestamptz not null default now());
create table public.domains (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), domain_name text unique not null, status text not null default 'pending', registered_at timestamptz, expires_at timestamptz, auto_renew boolean not null default true, provider_reference text, created_at timestamptz not null default now());
create index domains_customer_idx on public.domains(customer_id); create index domains_expiry_idx on public.domains(expires_at);
create table public.domain_contacts (id uuid primary key default gen_random_uuid(), domain_id uuid not null references public.domains(id) on delete cascade, kind text not null, full_name text not null, email text not null, phone text, address jsonb not null default '{}'::jsonb);
create table public.nameservers (id uuid primary key default gen_random_uuid(), domain_id uuid not null references public.domains(id) on delete cascade, hostname text not null, position smallint not null, unique(domain_id,position));
create table public.dns_records (id uuid primary key default gen_random_uuid(), domain_id uuid not null references public.domains(id) on delete cascade, type text not null, name text not null, value text not null, ttl integer not null default 3600, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), order_number text unique not null, status public.order_status not null default 'pending', currency text not null default 'AUD', subtotal_cents integer not null, tax_cents integer not null default 0, total_cents integer not null, created_at timestamptz not null default now());
create index orders_customer_idx on public.orders(customer_id); create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), description text not null, quantity integer not null default 1, unit_amount_cents integer not null, metadata jsonb not null default '{}'::jsonb);
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), provider text not null default 'stripe', provider_reference text, status text not null, amount_cents integer not null, created_at timestamptz not null default now());
create table public.invoices (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), order_id uuid references public.orders(id), number text unique not null, status text not null, due_at timestamptz, created_at timestamptz not null default now());
create table public.hosting_plans (id uuid primary key default gen_random_uuid(), product_id uuid unique references public.products(id), storage_gb integer, websites integer, features jsonb not null default '[]'::jsonb);
create table public.hosting_accounts (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), plan_id uuid references public.hosting_plans(id), primary_domain text, status text not null default 'pending', provider_reference text, created_at timestamptz not null default now());
create table public.ssl_products (id uuid primary key default gen_random_uuid(), product_id uuid unique references public.products(id), validation_type text, validity_months integer);
create table public.ssl_certificates (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), product_id uuid references public.ssl_products(id), domain_name text not null, status text not null, issued_at timestamptz, expires_at timestamptz, provider_reference text);
create table public.email_plans (id uuid primary key default gen_random_uuid(), product_id uuid unique references public.products(id), inboxes integer, storage_gb integer);
create table public.email_accounts (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), plan_id uuid references public.email_plans(id), email text unique not null, status text not null default 'pending');
create table public.support_tickets (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), subject text not null, category text, priority text not null default 'normal', status text not null default 'open', created_at timestamptz not null default now()); create table public.support_messages (id uuid primary key default gen_random_uuid(), ticket_id uuid not null references public.support_tickets(id) on delete cascade, author_id uuid references public.profiles(id), body text not null, attachments jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create table public.coupons (id uuid primary key default gen_random_uuid(), code text unique not null, percent_off integer check(percent_off between 1 and 100), amount_off_cents integer, active boolean not null default true, expires_at timestamptz); create table public.subscriptions (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), product_id uuid references public.products(id), status text not null, provider_reference text, created_at timestamptz not null default now()); create table public.activity_logs (id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), action text not null, entity_type text, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.customers enable row level security; alter table public.domains enable row level security; alter table public.dns_records enable row level security; alter table public.nameservers enable row level security; alter table public.orders enable row level security; alter table public.support_tickets enable row level security;
create policy "read own profile" on public.profiles for select using (auth.uid()=id); create policy "update own profile" on public.profiles for update using(auth.uid()=id); create policy "read own customer" on public.customers for select using(profile_id=auth.uid()); create policy "read own domains" on public.domains for select using(customer_id in(select id from public.customers where profile_id=auth.uid())); create policy "read own dns" on public.dns_records for select using(domain_id in(select d.id from public.domains d join public.customers c on c.id=d.customer_id where c.profile_id=auth.uid())); create policy "read own nameservers" on public.nameservers for select using(domain_id in(select d.id from public.domains d join public.customers c on c.id=d.customer_id where c.profile_id=auth.uid())); create policy "read own orders" on public.orders for select using(customer_id in(select id from public.customers where profile_id=auth.uid())); create policy "read own tickets" on public.support_tickets for select using(customer_id in(select id from public.customers where profile_id=auth.uid()));
